<script setup lang="ts">
import { ref, watch } from 'vue'
import { useLessonReviewStore } from '@/stores/lessonReview'
import { formatReviewTime } from '@/utils/lessonReview'
import AppIcon from '@/components/common/AppIcon.vue'
withDefaults(defineProps<{ compact?: boolean }>(), { compact: false })
const store = useLessonReviewStore()
const video = ref<HTMLVideoElement | null>(null)
const mediaError = ref('')
const ready = ref(false)
function syncSeek() { if (video.value && ready.value) { video.value.pause(); video.value.currentTime = store.currentTime } }
function loaded() { ready.value = true; mediaError.value = ''; syncSeek() }
function update() { if (video.value) store.updateTime(video.value.currentTime) }
async function toggle() {
  if (!video.value || !ready.value) return
  if (!video.value.paused) video.value.pause()
  else try { await video.value.play() } catch { mediaError.value = '浏览器未能播放该录像，请使用视频控件重试。' }
}
function retry() { mediaError.value = ''; video.value?.load() }
watch(() => store.seekVersion, syncSeek)
watch(() => store.data?.lesson.video_url, () => { ready.value = false; mediaError.value = '' })
</script>
<template>
  <section id="review" class="panel lesson-player" :class="{ compact }" data-testid="lesson-player">
    <div class="panel-heading"><div><h2>{{ compact ? '原始课堂' : '回到课堂' }}</h2><p>{{ compact ? '同一录像 · 同一时间轴' : '语音、课件与行为证据，共用原录像时间' }}</p></div><span class="tag">{{ store.isPlaying ? '播放中' : '待回看' }}</span></div>
    <div class="lesson-video-stage"><video v-if="store.data?.lesson.video_url" ref="video" :key="store.data.lesson.video_url" :src="store.data.lesson.video_url" controls playsinline preload="metadata" @loadedmetadata="loaded" @timeupdate="update" @seeked="update" @play="store.isPlaying = true" @pause="store.isPlaying = false" @ended="store.isPlaying = false" @error="mediaError = '课堂录像暂时无法访问。时间定位与文本证据仍可使用。'; store.isPlaying = false"></video><div v-if="!store.data?.lesson.video_url || mediaError" class="lesson-video-error"><AppIcon name="film" :size="30" /><p>{{ mediaError || '本课尚未提供可播放录像' }}</p><button v-if="store.data?.lesson.video_url" class="btn" @click="retry">重试录像</button></div></div>
    <div class="lesson-play-controls"><button class="lesson-play-btn" :disabled="!ready || !!mediaError" :aria-label="store.isPlaying ? '暂停课堂录像' : '播放课堂录像'" @click="toggle"><AppIcon :name="store.isPlaying ? 'pause' : 'play'" :size="16" /></button><span class="mono">{{ store.timeText }}</span><input aria-label="整堂课回放进度" type="range" min="0" :max="store.duration" step="0.01" :value="store.currentTime" @input="store.seek(Number(($event.target as HTMLInputElement).value))" /><span class="mono">{{ store.durationText }}</span><button class="icon-btn" aria-label="回到课程起点" @click="store.seek(0)"><AppIcon name="reset" :size="15" /></button></div>
    <div v-show="!compact" class="evidence-timeline"><div class="timeline-row"><span>语音</span><div><button v-for="segment in store.displayTranscripts" :key="segment.id" :style="{ left: `${segment.start_sec / store.duration * 100}%`, width: `${Math.max(.12, (segment.end_sec - segment.start_sec) / store.duration * 100)}%` }" :class="{ current: store.transcripts.some(t => t.id === segment.id) }" :title="`${formatReviewTime(segment.start_sec)} ${segment.text}`" :aria-label="`定位语音 ${segment.id} ${formatReviewTime(segment.start_sec)}`" @click="store.seek(segment.start_sec)"></button><i :style="{ left: `${store.currentTime / store.duration * 100}%` }"></i></div></div><div class="timeline-row slides"><span>课件</span><div><button v-for="slide in store.observedSlides" :key="slide.id" :style="{ left: `${slide.start_sec / store.duration * 100}%`, width: `${Math.max(.12, (slide.end_sec - slide.start_sec) / store.duration * 100)}%` }" :class="{ current: store.currentSlide?.id === slide.id }" :title="`${formatReviewTime(slide.start_sec)} ${slide.title}`" :aria-label="`定位课件 ${slide.id} ${formatReviewTime(slide.start_sec)}`" @click="store.seek(slide.start_sec)"></button><i :style="{ left: `${store.currentTime / store.duration * 100}%` }"></i></div></div><p>色块仅表示证据所在区间 · 空白为暂无记录 · 点击定位</p></div>
    <div v-show="!compact" class="current-speech"><span>此刻在讲{{ store.data?.teacher_transcript ? (store.currentDisplayTranscripts.length && store.currentDisplayTranscripts.every(t => t.teacher?.human_verified) ? ' · 教师已核对' : ' · 含机器上下文，未核验') : store.data?.transcript_proofreading ? ' · 机器校对待核验' : '' }}</span><p v-if="store.currentDisplayTranscripts.length">{{ store.currentDisplayTranscripts.map(t => t.text).join(' ') }}</p><p v-else class="speech-gap">当前时刻没有对应的转写片段，可播放原录像核对。</p></div>
  </section>
</template>
<style scoped>
