.compact .panel-heading{padding:17px 16px 13px}.compact .panel-heading h2{font-size:12px}.compact .panel-heading p{font-size:9px}.compact .panel-heading .tag{font-size:8px;padding:4px 6px}.compact .lesson-video-stage{margin:0 12px}.compact .lesson-play-controls{padding:13px 12px;gap:7px;font-size:9px}.compact .lesson-play-btn{width:25px;height:25px}.compact .lesson-play-controls .icon-btn{width:23px}.compact .lesson-play-controls input{min-width:20px}@media(max-width:750px){.compact .lesson-video-stage{max-height:240px;aspect-ratio:auto;height:200px}.compact .lesson-video-stage video{object-fit:contain}}
@media(max-width:550px){.lesson-video-stage{margin:0 14px}.lesson-play-controls{padding:14px;gap:8px}.evidence-timeline{padding-left:15px;padding-right:15px}.current-speech{padding:15px 17px 20px}}
.lesson-play-btn{background:linear-gradient(140deg,#347af0,#2059c9);box-shadow:0 3px 9px #245edb24}.lesson-play-btn:hover:not(:disabled){box-shadow:0 4px 13px #245edb40;transform:scale(1.05)}.lesson-video-stage{background:#11284d;border:1px solid #d8e5f8}.timeline-row button{background:#9dc0f2;transition:background .18s}.timeline-row button.current{background:#3975dc}.timeline-row.slides button{background:#bfd4f7}.timeline-row.slides button.current{background:#699be5}.lesson-play-controls input{accent-color:#3478e8}.current-speech{background:linear-gradient(120deg,#f5f9ff,#fff)}.current-speech>span{color:#7b96bc}.current-speech p{color:#4a6d9f}.evidence-timeline{border-bottom-color:#e4ecf8}.timeline-row>div{background:#edf3fd}
</style>
